// Alert only when something is wrong; the 8:00 run always sends a one-line summary. No question text, no names.
const st = $('Vision service status').first().json;
const n = $input.first().json;
const up = !st.error && typeof st.queued === 'number';
const problems = [];
if (!up) problems.push('the vision service is NOT responding (launchctl kickstart -k gui/$(id -u)/com.example.rag-vision; log ~/Library/Logs/rag-vision.log)');
if (Number(n.failed_files) > 0) problems.push(`${n.failed_files} file(s) failed to index:\n${n.failed_examples || ''}`);
if (Number(n.stuck_files) > 0) problems.push(`${n.stuck_files} file(s) stuck in the queue for 2+ hours`);
const hour = new Date().getHours();
if (!problems.length && hour !== 8) return [];
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const head = problems.length ? '⚠️ <b>Visual search needs attention</b>' : '✅ <b>Visual search OK</b>';
const line = `${Number(n.ok_files)} files indexed (${Number(n.views).toLocaleString('en-US')} page views)` +
  (up ? `, queue ${st.queued}` : '') + (Number(n.not_indexed) ? `, ${n.not_indexed} waiting` : '');
return [{ json: { text: [head, esc(line), ...problems.map(p => '• ' + esc(p))].join('\n') } }];
